  await save('reopened-workspace.json',reopenedBundle.body,reopenedBundle.type);
  await save('reopened-collection.json',recoveredJson);
  await save('reopened-collection.html',recoveredReport.body,recoveredReport.type);
  const newBundle=JSON.parse(reopenedBundle.body);
  for(const key of ['connections','captures','reviews','collections'])same(newBundle.payload[key],bundle.payload[key],'Reopened full workspace '+key+' differs');
  for(const operation of bundle.payload.operations)same(newBundle.payload.operations.find(item=>item.requestId===operation.requestId),operation,'Retained operation changed during receiving');
  journey.checks.push({name:'browser-v2-receive-native-reopen',workspaceId:receivedState.workspaceId,
    sourceRevision:bundle.payload.workspace.revision,receivedRevision:receivedState.revision,collections:3,rows:rows.length,
    sourceOperations:bundle.payload.operations.length});
  assert(journey.browserErrors.length===0,'Browser page errors occurred');
  journey.state='passed';journey.workspaceId=receivedState.workspaceId;
}catch(error){
  journey.state='failed';journey.error={message:error.message,code:error.code,status:error.status,details:error.details,stack:error.stack};
  process.exitCode=1;
}finally{
  releaseSource();
  if(provider)await provider.close().catch(error=>{journey.closeError=error.message;});
  if(browser)await browser.close().catch(error=>{journey.browserCloseError=error.message;});
  for(const instance of instances.reverse())await instance.close().catch(error=>{journey.closeError=error.message;journey.state='failed';process.exitCode=1;});
  journey.completedAt=now();
  await writeFile(join(output,'journey.json'),json(journey),{mode:0o600,flag:'wx'});
  console.log(JSON.stringify({state:journey.state,runId:journey.runId,output,checks:journey.checks.length,files:journey.files.length,error:journey.error}));
}
